#pragma once
#include <Windows.h>
#include <TlHelp32.h>
#include "AppUpdateData.h"
#include <chrono>
namespace UpdaterFiles {
using Path=std::filesystem::path;
inline bool Id(const std::wstring& name){return name.size()==32&&std::all_of(name.begin(),name.end(),[](wchar_t c){return(c>=L'0'&&c<=L'9')||(c>=L'a'&&c<=L'f');});}
inline bool Normal(const Path& path){if(!path.is_absolute()||path.lexically_normal()!=path)return false;Path current=path.root_path();for(const auto& part:path.relative_path()){current/=part;const auto attributes=GetFileAttributesW(current.c_str());if(attributes==INVALID_FILE_ATTRIBUTES||(attributes&FILE_ATTRIBUTE_REPARSE_POINT))return false;}return true;}
inline Path Replacement(const Path& target,const std::wstring& id){if(!Id(id)||target.extension()!=L".exe"||!target.is_absolute()||target.lexically_normal()!=target)throw std::runtime_error("Invalid updater replacement path.");return target.parent_path()/(target.filename().wstring()+L".update-"+id+L".exe");}
inline bool Running(const Path& file){HANDLE snapshot=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if(snapshot==INVALID_HANDLE_VALUE)return true;struct Close{HANDLE h;~Close(){CloseHandle(h);}}close{snapshot};PROCESSENTRY32W process{};process.dwSize=sizeof(process);if(!Process32FirstW(snapshot,&process))return true;do{HANDLE handle=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,process.th32ProcessID);if(!handle)continue;wchar_t path[32768]{};DWORD length=32768;const bool same=QueryFullProcessImageNameW(handle,0,path,&length)&&_wcsicmp(file.c_str(),path)==0;CloseHandle(handle);if(same)return true;}while(Process32NextW(snapshot,&process));return false;}
inline bool ParentActive(const OffsetData::Json& request){const auto value=OffsetData::Uint(request.At("parent_pid"));if(!value||value>0xffffffffu)return true;HANDLE handle=OpenProcess(SYNCHRONIZE|PROCESS_QUERY_LIMITED_INFORMATION,FALSE,static_cast<DWORD>(value));if(!handle)return GetLastError()!=ERROR_INVALID_PARAMETER;struct Close{HANDLE h;~Close(){CloseHandle(h);}}close{handle};if(WaitForSingleObject(handle,0)==WAIT_OBJECT_0)return false;FILETIME started{},exit{},kernel{},user{};if(!GetProcessTimes(handle,&started,&exit,&kernel,&user))return true;const auto actual=(std::uint64_t(started.dwHighDateTime)<<32)|started.dwLowDateTime;std::uint64_t expected=0;const auto text=request.At("parent_started").Str();const auto converted=std::from_chars(text.data(),text.data()+text.size(),expected);return converted.ec!=std::errc()||converted.ptr!=text.data()+text.size()||actual==expected;}
inline void RemoveReplacement(const Path& target,const std::wstring& id){try{const auto file=Replacement(target,id);if(Normal(file)&&std::filesystem::is_regular_file(file)&&!Running(file)){std::error_code error;std::filesystem::remove(file,error);}}catch(...) {}}
inline void Cleanup(const Path& storage,const Path& executable){try{const auto root=storage/L"stage";if(!Normal(root)||!std::filesystem::is_directory(root))return;for(const auto& entry:std::filesystem::directory_iterator(root)){const auto stage=entry.path();if(!Id(stage.filename().wstring())||!Normal(stage)||!entry.is_directory()||Running(stage/L"helper.exe"))continue;bool abandoned=false;const auto requestFile=stage/L"request.json";if(Normal(requestFile)&&std::filesystem::is_regular_file(requestFile)){try{const auto request=OffsetData::Parse(AppUpdateData::Read(requestFile,65536));const auto target=std::filesystem::u8path(request.At("target").Str());if(target!=executable||ParentActive(request))continue;const auto release=AppUpdateData::Manifest(request.At("envelope").Str());const auto replacement=Replacement(target,stage.filename().wstring());if(std::filesystem::exists(replacement)){if(!Normal(replacement)||Running(replacement))continue;AppUpdateData::Binary(replacement,release);RemoveReplacement(target,stage.filename().wstring());if(std::filesystem::exists(replacement))continue;}abandoned=true;}catch(...){continue;}}
else abandoned=std::filesystem::file_time_type::clock::now()-entry.last_write_time()>std::chrono::hours(24);
if(!abandoned)continue;for(const wchar_t* name:{L"helper.exe",L"download.exe",L"previews.cab",L"preview-cache.cab",L"custom-textures.cab",L"custom-textures-v2.cab",L"request.json",L"request.json.tmp"}){const auto file=stage/name;if(Normal(file)&&std::filesystem::is_regular_file(file)){std::error_code error;std::filesystem::remove(file,error);}}std::error_code error;std::filesystem::remove(stage,error);}}catch(...) {}}
}
